import { z } from 'zod'

// Applies to the passwords being set. The login and the current password are not checked against
// it, so that users whose password predates these limits can still authenticate.
export const newPasswordSchema = z.string().min(6).max(20)

// Emails are stored trimmed and in lower case, so that the unique index ignores case
export const emailSchema = z.string().trim().toLowerCase().email()

// The password is generated by the backend
export const createUserSchema = z.object({
  name: z.string().trim().min(1),
  email: emailSchema
}).strict()

export const updatePasswordSchema = z.object({
  currentPassword: z.string().max(20),
  newPassword: newPasswordSchema
})

export const updateUserSchema = z.object({
  name: z.string()
})

export const usersQuerySchema = z.object({
  search: z.string().trim().max(100).optional()
})
